\label{prop:galois:properties}
  Each form \(\ensuremath{\left\langle \cdot, \cdot \right\rangle}_{\phi_i}\) for \(i \in \ZZ_d\) is \(\phi_i\)-sesquilinear, \(\FF_q\)-linear in the first argument, \(\FF_p\)-linear in the second argument, and admits \(\ensuremath{\left\langle \ensuremath{\mathbf{x}}\xspace, \ensuremath{\mathbf{y}}\xspace \right\rangle}_{\phi_i} = \phi_i(\ensuremath{\left\langle \ensuremath{\mathbf{y}}\xspace, \ensuremath{\mathbf{x}}\xspace \right\rangle}_{\phi_{-i}})\).
  In particular, it is a Hermitian form if and only if either \(i=0\) or \(d\) is even and \(i=\frac{d}{2}\).

\label{def:moore}
  Let \(q = p^d\) and \(n,m \in \NN\). For \(a_1,\dots,a_n \in \FF_q\), the \emph{Moore matrix} is defined as
  \begin{align*}
    \ensuremath{\mathbf{M}}\xspace_{m}(a_1,\dots,a_n)
    &=
    \begin{bmatrix}
      a_1 & a_1^{p} & \dots & a_1^{p^{m-1}} \\
      a_2 & a_2^{p} & \dots & a_2^{p^{m-1}} \\
      \vdots & \vdots & \ddots & \vdots \\
      a_n & a_n^{p} & \dots & a_n^{p^{m-1}}
    \end{bmatrix} 
    =
    \begin{bmatrix}
      a_1 & \phi_1(a_1) & \dots & \phi_{m-1}(a_1) \\
      a_2 & \phi_1(a_2) & \dots & \phi_{m-1}(a_2) \\
      \vdots & \vdots & \ddots & \vdots \\
      a_n & \phi_1(a_n) & \dots & \phi_{m-1}(a_n) \\
    \end{bmatrix}.
  \end{align*}
  When \(n=m \geq 2\) and the Moore matrix is square, the \emph{Moore determinant} is equal to
  \begin{align*}
    &\det(\ensuremath{\mathbf{M}}\xspace_n(a_1,\dots,a_n)) 
    = \prod_{i=1}^{n} \prod_{c_1,\dots,c_{i-1} \in \FF_p} (c_1 a_1 + \cdots + c_{i-1} a_{i-1} + a_i).
  \end{align*}
  The Moore determinant is non-zero if and only if \(a_1,\dots,a_n \in \FF_q\) are \(\FF_p\)-linearly independent.

The codes \(\set{\ensuremath{\mathbf{0}}\xspace^n}\) and \(\FF_q^n\) are always LCD, hence we assume \(0 < k < n\). Since \(\ensuremath{\mathfrak{C}}\) is LCD if and only if \(\ensuremath{\mathfrak{C}}^\perp\) is LCD, we may further assume \(0 < k \leq \frac{n}{2}\). We use the mass formula from~\cite[Thm.~31 \& Cor.~32]{ITIT:CMTQ19}. Denote the probability in question by \(p_{n,k,q}^0 = \frac{\mathcal{X}_{n,k,q}^0}{\mathcal{X}_{n,k,q}}\). We use the standard fact that \(\genfrac{[}{]}{0pt}{}{n}{k}_{q} = q^{k \cdot (n-k)} \prod_{i=1}^{k} \frac{1 - q^{-(n-k+i)}}{1 - q^{-i}}\) and the analogous formula for \(\genfrac{[}{]}{0pt}{}{n}{k}_{q^2}\). We will bound the denominators simply using \(1 - q^{-m} \leq 1\) for \(m \in \NN\) and the numerators by observing that for any \(s \geq 1\) we have
  \begin{align*}
    \prod_{i=1}^{s} (1 - q^{-i})
    &\geq \prod_{i=1}^{\infty} (1 - q^{-i})
    \overset{\bullet}{\geq} 1 - \sum_{i=1}^{\infty} q^{-i} 
    = 1 - \frac{q^{-1}}{1 - q^{-1}}
    = 1 - \frac{1}{q-1}
  \end{align*}
  by the Weierstrass product inequality. We need to consider the four cases of \cref{prop:count:lcd}.

  \paragraph*{Case \(k\) odd and \(n\) odd}
  We write \(N = \frac{n - 1}{2}\) and \(K = \frac{k - 1}{2}\). \cref{prop:count:lcd} gives \(\lvert \mathcal{X}_{n,k,q}^0 \rvert = q^\frac{(k+1) \cdot (n-k)}{2} \genfrac{[}{]}{0pt}{}{N}{K}_{q^2}\) and we have \(\genfrac{[}{]}{0pt}{}{N}{K}_{q^2} = q^{2 K \cdot (N - K)} \prod_{i=1}^{K} \frac{1 - q^{-2 \cdot (N - K + i)}}{1 - q^{-2 i}}\). Since \(\frac{(k+1) \cdot (n-k)}{2} + 2 K \cdot (N-K) = k \cdot (n-k)\), the positive power of \(q\) cancels in \(p_{n,k,q}^0\), and so do the factors \(1 - q^{-a}\) for even \(a\), so we get
  \begin{align*}
    p_{n,k,q}^0
    &= \prod_{i=1}^{K} \frac{1 - q^{-(2 i - 1)}}{1 - q^{-(n - k + 2 i - 1)}} \cdot \frac{1 - q^{-(2 K + 1)}}{1 - q^{-(n - k + 2 K + 1)}} 
    \overset{\bullet}{\geq} 1 - \frac{1}{q-1},
  \end{align*}
  where for \(\bullet\) we bound the numerators and denominators as discussed above.

  \paragraph*{Case \(k\) even and \(n\) odd}
  We write \(N = \frac{n-1}{2}\) and \(K = \frac{k}{2}\). \cref{prop:count:lcd} gives \(\lvert \mathcal{X}_{n,k,q}^0 \rvert = q^\frac{k \cdot (n-k+1)}{2} \genfrac{[}{]}{0pt}{}{N}{K}_{q^2}\) and we have \(\genfrac{[}{]}{0pt}{}{N}{K}_{q^2} = q^{2 K \cdot (N - K)} \prod_{i=1}^{K} \frac{1 - q^{-2 \cdot (N - K + i)}}{1 - q^{-2 i}}\). Since \(\frac{k \cdot (n-k+1)}{2} + 2 K \cdot (N-K) = k \cdot (n-k)\), the positive power of \(q\) cancels in \(p_{n,k,q}^0\), and so do the factors \(1 - q^{-a}\) for even \(a\), so we get
  \[
    p_{n,k,q}^0
    = \prod_{i=1}^{K} \frac{1 - q^{-(2 i - 1)}}{1 - q^{-(n - k + 2 i)}}
    \overset{\bullet}{\geq} 1 - \frac{1}{q-1},
  \]
  where for \(\bullet\) we bound the numerators and denominators as discussed above.

  \paragraph*{Case \(k\) even and \(n\) even}
  We write \(N = \frac{n}{2}\) and \(K = \frac{k}{2}\). \cref{prop:count:lcd} gives \(\lvert \mathcal{X}_{n,k,q}^0 \rvert = q^\frac{k \cdot (n-k)}{2} \genfrac{[}{]}{0pt}{}{N}{K}_{q^2}\) and we have \(\genfrac{[}{]}{0pt}{}{N}{K}_{q^2} = q^{2 K \cdot (N - K)} \prod_{i=1}^{K} \frac{1 - q^{-2 \cdot (N - K + i)}}{1 - q^{-2 i}}\). The positive power of \(q\) cancels in \(p_{n,k,q}^0\), and so do the factors \(1 - q^{-a}\) for even \(a\), so we get
  \[
    p_{n,k,q}^0
    = \prod_{i=1}^{K} \frac{1 - q^{-(2 i - 1)}}{1 - q^{-(n - k + 2 i - 1)}}
    \overset{\bullet}{\geq} 1 - \frac{1}{q-1},
  \]
  where for \(\bullet\) we bound the numerators and denominators as discussed above.

  \paragraph*{Case \(k\) odd and \(n\) even}
  This is the only anomalous case, as we have the additional factor \(A = q^\frac{n}{2} - \chi_q(-1)^\frac{n}{2}\). We write \(N = \frac{n}{2}\) and \(K = \frac{k-1}{2}\). \cref{prop:count:lcd} gives \(\lvert \mathcal{X}_{n,k,q}^0 \rvert = q^\frac{k \cdot (n-k) - 1}{2} \cdot \left(q^N - \chi_q(-1)^N\right) \cdot \genfrac{[}{]}{0pt}{}{N-1}{K}_{q^2}\) and we have \(\genfrac{[}{]}{0pt}{}{N-1}{K}_{q^2} = q^{2 K \cdot (N - 1 - K)} \prod_{i=1}^{K} \frac{1 - q^{-2 \cdot (N - 1 - K + i)}}{1 - q^{-2 i}}\). We use \(q^N - \chi_q(-1)^N = q^N \cdot (1 - \chi_q(-1)^N \cdot q^{-N})\) to get
  \[
    p_{n,k,q}^0
    = \frac{1 - \chi_q(-1)^N q^{-N}}{1 - q^{-n}} \prod_{i=1}^{K} \frac{1 - q^{-(2 i - 1)}}{1 - q^{-(n - k + 2 i)}}.
  \]
  When \(\chi_q(-1)^N = -1\), we have \(\frac{1 + q^{-N}}{1 - q^{-n}} = \frac{1}{1 - q^{-N}} \geq 1\) and bound as in the other cases. Otherwise \(\chi_q(-1)^N = 1\) and we have for \(N = 1\) that \(p_{2,1,q}^0 = \frac{1 - q^{-1}}{1 - q^{-2}} = \frac{q}{q+1} \geq 1 - \frac{1}{q-1}\). When \(N \geq 2\), we have \(\frac{1 - q^{-N}}{1 - q^{-n}} = \frac{1}{1 + q^{-N}} \geq \frac{1}{1 + q^{-2}}\). The product of odd negative powers in the numerator can be better bounded by \(1 - \frac{q}{q^2 - 1}\), and we finally get
  \begin{align*}
    \frac{1}{1 + q^{-2}} \cdot \left( 1 - \frac{q}{q^2 - 1} \right)
    &= \frac{q^2}{q^2 + 1} \cdot \left( 1 - \frac{q}{q^2 - 1} \right) 
    \geq 1 - \frac{1}{q-1}. \qedhere
  \end{align*}

\label{def:hollow:plane}
  Let \(n, q \in \ZZ\) with \(n \geq 2\) and \(q\) prime power. A \emph{regular plane} is an LCD code over \(\FF_q\) of dimension \(2\) and length \(n\).
  A regular plane generated by \(\ensuremath{\mathbf{T}}\xspace\) is \emph{hyperbolic} if \(V_\ensuremath{\mathbf{T}}\xspace\) is isometric to a hyperbolic plane, equivalently \(\chi_\ensuremath{\mathbf{T}}\xspace = \chi_q(-1)\).

The high-level proof idea is the following. The algorithm will first transform its input matrix such that its last two rows span a hyperbolic plane using \cref{lem:algo:findplane:hyper}. Let \(x, y\) be variables over \(\FF_q\). Every vector \(\ensuremath{\mathbf{v}}\xspace \in \FF_q^{k-2}\) defines a smooth conic \(f_\ensuremath{\mathbf{v}}\xspace(x, y) = \ensuremath{\mathbf{x}}\xspace^\mathtt{T} \ensuremath{\mathbf{A}}\xspace \ensuremath{\mathbf{A}}\xspace^\mathtt{T} \ensuremath{\mathbf{x}}\xspace\), where \(\ensuremath{\mathbf{x}}\xspace = [\ensuremath{\mathbf{v}}\xspace \; \Vert \; x \; \Vert \; y]\), whose points are in bijection with elements of \(\ensuremath{\mathcal{V}}_{\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace)}\) by \cref{prop:so-variety}. All conics in the family share the same discriminant independent of \(\ensuremath{\mathbf{A}}\xspace\), since we always pick a hyperbolic plane. Then by \cref{prop:conic} each of these conics has a non-empty zero set, however, they may be of two different possible sizes (for a fixed discriminant), thus we weight these points differently depending on which conic they lie on, allowing us to sample uniformly from \(\ensuremath{\mathcal{V}}_{\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace)}\) by simply sampling \(\ensuremath{\mathbf{v}}\xspace \sample \FF_q^{k-2}\) and sampling from the set of points on \(f_\ensuremath{\mathbf{v}}\xspace\) with potential rejection to correct the distribution. We discuss efficiency and correctness, failure probability, and uniformity of the output.

  \paragraph*{Efficiency and correctness}
  Assume the algorithm \(\ensuremath{\mathsf{SSO}}\xspace\) returns a vector \(\ensuremath{\mathbf{y}}\xspace\), then \(\ensuremath{\mathbf{y}}\xspace \in \ensuremath{\mathcal{V}}_\ensuremath{\mathfrak{C}}\) by \cref{prop:so-variety}. Denote by \(\ensuremath{\mathsf{halt}}\xspace = n\) the maximal number of loop repetitions. The algorithm first uses linear algebra (\cref{lem:algo:findplane}) to find a hyperbolic plane in the code generated by \(\ensuremath{\mathbf{A}}\xspace\) and compute the discriminant \(D\), then samples at most \(\ensuremath{\mathsf{halt}}\xspace \cdot (k-2)\) elements from \(\FF_q\), solves \(\ensuremath{\mathsf{halt}}\xspace\) conic equations over \(\FF_q\), samples once from a set with at most \(2 q - 1\) elements, and computes one multiplication of \(\ensuremath{\mathbf{A}}\xspace\) with the vector \([c_i]_{i=1}^k\). Computing the solutions to the conic equation na{\"\i}vely requires the computation of the Jacobi symbol, a square root~\cite[Sec.~1.5.1]{Cohen1993} and an inverse~\cite[Sec.~1.6]{Cohen1993}, each \(q\) times, together costing \(\bigO{q \log^4(q)}\). The worst-case cost of running the algorithm is therefore \(\bigO{n^\omega + \ensuremath{\mathsf{halt}}\xspace k q \log^4(q) + k^2}\), and we may fold the term \(k^2\) into \(n^\omega\).

  \paragraph*{Failure probability}
  Since \(k-h \geq 2\), there either exists a hyperbolic plane in \(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace)\) by \cref{lem:hollow:plane} and we may find it efficiently using \cref{lem:algo:findplane:hyper}, or all self-orthogonal vectors lie in \(\operatorname{hull}(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace))\). In the latter case, we return a uniformly random element of \(\operatorname{hull}(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace))\). In the former case, assume without loss of generality that \(\ensuremath{\left\langle \ensuremath{\mathbf{A}}\xspace[k-1], \ensuremath{\mathbf{A}}\xspace[k-1] \right\rangle} \ensuremath{\left\langle \ensuremath{\mathbf{A}}\xspace[k], \ensuremath{\mathbf{A}}\xspace[k] \right\rangle} \neq \ensuremath{\left\langle \ensuremath{\mathbf{A}}\xspace[k-1], \ensuremath{\mathbf{A}}\xspace[k] \right\rangle}^2\). For every choice of \(c_1,\dots,c_{k-2}\), the function \(F(x,y)\) defines a smooth affine conic. Indeed, the coefficient \(a\) of \(x^2\) is \(\ensuremath{\left\langle \ensuremath{\mathbf{A}}\xspace[k-1], \ensuremath{\mathbf{A}}\xspace[k-1] \right\rangle}\), the coefficient \(b\) of \(x y\) is \(2 \ensuremath{\left\langle \ensuremath{\mathbf{A}}\xspace[k-1], \ensuremath{\mathbf{A}}\xspace[k] \right\rangle}\), the coefficient \(c\) of \(y^2\) is \(\ensuremath{\left\langle \ensuremath{\mathbf{A}}\xspace[k], \ensuremath{\mathbf{A}}\xspace[k] \right\rangle}\), hence the discriminant of \(F(x,y)\) is
  \begin{align*}
    D_\ensuremath{\mathbf{A}}\xspace
    = b^2 - 4 a c
    &= 4 \ensuremath{\left\langle \ensuremath{\mathbf{A}}\xspace[k-1], \ensuremath{\mathbf{A}}\xspace[k] \right\rangle}^2 
    - 4 \ensuremath{\left\langle \ensuremath{\mathbf{A}}\xspace[k-1], \ensuremath{\mathbf{A}}\xspace[k-1] \right\rangle} \ensuremath{\left\langle \ensuremath{\mathbf{A}}\xspace[k], \ensuremath{\mathbf{A}}\xspace[k] \right\rangle},
  \end{align*}
  which is non-zero in \(\FF_q\) since \(q\) is odd. Recall that since we chose a hyperbolic plane, we have from \cref{prop:conic} that \(D_\ensuremath{\mathbf{A}}\xspace \in \chi_q^{-1}(1)\) and so the number of conic solutions is \(S \in \set{q-1,2 q - 1}\). The algorithm can only return \(\bot\) if for each of the \(\ensuremath{\mathsf{halt}}\xspace\) repetitions the conic \(F(x,y)\) has \(q-1\) solutions and the algorithm sampled \(u \sample \ensuremath{\mathcal{U}\left( [0,1] \right)}\) such that \(u > \frac{q - 1}{2 q - 1}\) each time. Hence the failure probability is at most
  \[
    \left( \frac{q}{2 q - 1} \right)^\ensuremath{\mathsf{halt}}\xspace = 2^{\log\left( \frac{q}{2 q - 1} \right) \cdot n} < 2^{-\frac{n}{2}}.
  \]

  \paragraph*{Uniform output distribution}
  To show this algorithm samples from \(\ensuremath{\mathcal{U}\left( \ensuremath{\mathcal{V}}_\ensuremath{\mathfrak{C}} \right)}\), assume again that it did not halt with \(\bot\). We must show that every self-orthogonal vector \(\ensuremath{\mathbf{y}}\xspace \in \ensuremath{\mathcal{V}}_{\ensuremath{\mathfrak{C}}}\) is sampled with the same probability. Since a smooth affine conic always has at least \(1\) solution, we have by \cref{def:code:variety} that \(\ensuremath{\mathsf{SSO}}\xspace\) samples each vector in \(\ensuremath{\mathcal{V}}_\ensuremath{\mathfrak{C}}\) with non-zero probability. Let \(M = 2 q - 1\) be the maximum number of solutions to the obtained conic, which is \(2 q - 1\) since \(D_\ensuremath{\mathbf{A}}\xspace \in \chi_q^{-1}(1)\). Regardless of the number of solutions \(S\) to the obtained conic, the probability of each vector being sampled is
  \begin{align*}
    \condprob{\ensuremath{\mathbf{y}}\xspace \leftarrow \ensuremath{\mathsf{SSO}}\xspace(\ensuremath{\mathbf{A}}\xspace)}{\ensuremath{\mathbf{y}}\xspace \neq \bot}
    &= \frac{1}{q^{k-2}} \frac{1}{S} \probsub{u \sample [0,1]}{u \leq \frac{S}{M}} 
    = \frac{1}{q^{k-2}} \frac{1}{M}.
  \end{align*}
  Since \(M\) is fixed at the beginning of execution by the parametrisation of \(\ensuremath{\mathcal{V}}_\ensuremath{\mathfrak{C}}\) as a family of conics, the probability of each self-orthogonal vector being sampled must be the same, that is, \(\ensuremath{\mathsf{SSO}}\xspace\) conditioned on not aborting samples from \(\ensuremath{\mathcal{U}\left( \ensuremath{\mathcal{V}}_\ensuremath{\mathfrak{C}} \right)}\).

The proof is essentially one recursive step in the proof of~\cite[Thm.~5]{ITIT:LiShiLin25}. By~\cite[Thm.~6.26]{LidlNiederreiter1997} the number of self-orthogonal vectors in \(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace)^\perp\) does not depend on \(\ensuremath{\mathbf{A}}\xspace\) but only on the parameters \(n,k,h,q,\chi\). Indeed, as derived in~\cite[Prop.~6~\&~7]{ITIT:LiShiLin25}, an LCD code of square class \(\pm 1\) contains \(M_\pm(n,k,q) = q^{k-1} - 1\) non-zero vectors if \(k\) is odd and \(M_\pm(n,k,q) = \left(q^\frac{k}{2} \mp \chi_q(-1)^\frac{k}{2}\right) \cdot \left(q^{\frac{k}{2}-1} \pm \chi_q(-1)^\frac{k}{2}\right)\) if \(k\) is even (and \(M_\pm(n,k,q) = 0\) if \(k=0\)). Thus an \([n,k]\)-linear \(h\)-hollow code \(\ensuremath{\mathfrak{C}}\) over \(\FF_q\) of square class \(\chi\) has \(q^h M_\chi(n,k-h,q)\) vectors in \(\ensuremath{\mathcal{V}}_\ensuremath{\mathfrak{C}} \setminus \operatorname{hull}(\ensuremath{\mathfrak{C}})\), indeed \(\lvert \operatorname{hull}(\ensuremath{\mathfrak{C}}) \rvert\) many for each non-zero self-orthogonal vector of its LCD component.

  The square class of \(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace)^\perp\), denoted by \(\chi_{\ensuremath{\mathbf{A}}\xspace^\perp}\), is \(\chi_{\ensuremath{\mathbf{A}}\xspace^\perp} = \chi \chi_q(-1)^h\) by~\cite[Prop.~5]{ITIT:LiShiLin25}, thus from \(\operatorname{hull}(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace)) = \operatorname{hull}(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace)^\perp)\) we get \(\lvert \ensuremath{\mathcal{V}}_{\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace)^\perp} \setminus \operatorname{hull}(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace)) \rvert = q^h M_{\chi \chi_q(-1)^h}(n,n-k-h,q)\) independently of \(\ensuremath{\mathbf{A}}\xspace\). This number is \(0\) if and only if the set \(\mathcal{X}_{n,k+1,q}^{\chi,h+1}\) is empty (see~\cite[Rem.~3]{localinv}), so our statement is vacuously true -- there is no \(\ensuremath{\mathbf{y}}\xspace\) to sample from \(\ensuremath{\mathcal{V}}_{\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace)^\perp} \setminus \operatorname{hull}(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace))\) and there is no \(\dist_{n,k+1,q}^{\chi,h+1}\). Otherwise, the code \(\ensuremath{\mathfrak{C}}([\ensuremath{\mathbf{A}}\xspace \; \Vert \; \ensuremath{\mathbf{y}}\xspace^\mathtt{T}])\) (as any \(\ensuremath{\mathfrak{C}}\) of type \((h+1, \chi)\)) is by~\cite[Prop.~2]{ITIT:LiShiLin25} obtained from \((q^{h+1} - 1) \cdot q^{k}\) different \([n,k]\)-linear \(h\)-hollow codes over \(\FF_q\) with square class \(\chi\) by appending a self-orthogonal vector from its dual. Thus for any \(h\)-hollow code \(\ensuremath{\mathfrak{C}}\) of square class \(\chi\) we have
  \begin{align*}
    \probsub{\ensuremath{\mathbf{A}}\xspace \sample \dist_{n,k,q}^{\chi,h},\ensuremath{\mathbf{y}}\xspace \sample \ensuremath{\mathcal{V}}_{\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace)^\perp}\setminus\operatorname{hull}(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace))}{\ensuremath{\mathfrak{C}} = \ensuremath{\mathfrak{C}}([\ensuremath{\mathbf{A}}\xspace \; \Vert \; \ensuremath{\mathbf{y}}\xspace^\mathtt{T}])} 
    &= \prob{\ensuremath{\mathbf{A}}\xspace \sample \dist_{n,k,q}^{\chi,h}} \frac{(q^{h+1} - 1) \cdot q^k}{q^h M_{\chi \chi_q(-1)^h}(n,n-k-h,q)} \\
    &= \frac{1}{\left\lvert \mathcal{X}_{n,k,q}^{\chi,h} \right\rvert} \frac{(q^{h+1}-1) \cdot q^{k-h}}{M_{\chi \chi_q(-1)^h}(n,n-k-h,q)}
    \overset{\bullet}{=} \frac{1}{\left\lvert \mathcal{X}_{n,k+1,q}^{\chi,h+1} \right\rvert},
  \end{align*}
  where for \(\bullet\) we use~\cite[Thm.~5]{ITIT:LiShiLin25}, so the distribution of \(\ensuremath{\mathfrak{C}}([\ensuremath{\mathbf{A}}\xspace \; \Vert \; \ensuremath{\mathbf{y}}\xspace^\mathtt{T}])\) is indeed that of a uniformly random \([n,k+1]\)-linear \((h+1)\)-hollow code over \(\FF_q\) with square class \(\chi\). Multiplying by \(\ensuremath{\mathbf{U}}\xspace \sample \mathcal{GL}_{k+1}(\FF_q)\) then translates this statement to generator matrices, that is, \(\ensuremath{\mathbf{U}}\xspace \cdot [\ensuremath{\mathbf{A}}\xspace \; \Vert \; \ensuremath{\mathbf{y}}\xspace^\mathtt{T}]\) is distributed according to \(\dist_{n,k+1,q}^{\chi,h+1}\).

We discuss efficiency and correctness, failure probability and uniformity of the output distribution.

  \paragraph*{Efficiency and correctness}
  First assume the algorithm \(\ensuremath{\mathsf{SampleCode}}\xspace\) successfully outputs a matrix \(\ensuremath{\mathbf{A}}\xspace\). If \(h < k\) then the algorithm outputs a full-rank \(k \times n\) matrix over \(\FF_q\), since we start with a full-rank \((k-h) \times n\) matrix and append \(h\) rows that increment the rank, otherwise we return \(\bot\). The starting matrix \(\ensuremath{\mathbf{A}}\xspace_{(0)} \in \FF_q^{(k-h) \times n}\) is \(0\)-hollow, otherwise we return \(\bot\), and each appended row \(\ensuremath{\mathbf{y}}\xspace_{i}^\mathtt{T}\) increments the hull dimension. Indeed, \(\ensuremath{\mathbf{y}}\xspace_{i}\) is by \cref{lem:algo:sso} orthogonal to itself and every vector in the code \(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace_{(i-1)})\), since it belongs to the dual code of \(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace_{(i-1)})\). Since we exclude vectors that are in \(\operatorname{hull}(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace_{(i-1)})) \subseteq \ensuremath{\mathcal{V}}_{\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace_{(i-1)})^\perp}\), the vector \(\ensuremath{\mathbf{y}}\xspace_i\) is not already in \(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace_{(i-1)})\), thus adding it increments the rank. Clearly \(\ensuremath{\mathbf{y}}\xspace_{i}\) is also in the hull of \(\ensuremath{\mathbf{A}}\xspace_{(i)}\), hence also the hull dimension increments. Thus \(\ensuremath{\mathbf{A}}\xspace \in \FF_q^{k \times n}\) is \(h\)-hollow. Since \(\ensuremath{\mathbf{A}}\xspace_{(0)}\) is an LCD component of \(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace)\), we have that \(\chi_\ensuremath{\mathbf{A}}\xspace = \chi_{\ensuremath{\mathbf{A}}\xspace_{(0)}} = \chi\), thus \(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace) \in \mathcal{X}_{n,k,q}^{\chi,h}\). The argument for \(h=k\) is identical by remarking that the zero code \(\set{\ensuremath{\mathbf{0}}\xspace^n}\) is LCD as its dual is \(\FF_q^n\) and spanned by \(\ensuremath{\mathbf{I}}\xspace_n\). Hence in the first iteration we have \(\ensuremath{\mathbf{G}}\xspace = \ensuremath{\mathbf{I}}\xspace_n\) and we sample a uniformly random self-orthogonal vector \(\ensuremath{\mathbf{y}}\xspace_1\) from \(\FF_q^n\). The condition that \(\ensuremath{\mathbf{y}}\xspace_i\) is not in the hull of \(\ensuremath{\mathbf{A}}\xspace_{(i-1)}\) is in this case equivalent to linear independence, that is, the rank increases at every iteration and we end up with an \([n,k]\)-linear self-orthogonal code. Every step of the algorithm is efficient by \cref{lem:algo:samplelcd,lem:algo:sso}.

  \paragraph*{Failure probability}
  The algorithm \(\ensuremath{\mathsf{SampleLCD}}\xspace\) on input \(n,k-h,q,\chi\) always succeeds if \(h=k\) and otherwise succeeds with probability \(1 - \negl[k-h]\) and outputs a (uniformly random) \(0\)-hollow matrix \(\ensuremath{\mathbf{A}}\xspace_{(0)} \in \FF_q^{(k-h) \times n}\) with \(\chi_{\ensuremath{\mathbf{A}}\xspace_{(0)}} = \chi\) by \cref{lem:algo:samplelcd}. Observe that by repeating (at most) \(k\) times, the success probability rises to \(1 - \negl[(k-h) \cdot k] = 1 - \negl[k]\) by the same argument as in \cref{lem:algo:samplelcd}.

  Next, \(\ensuremath{\mathsf{SSO}}\xspace\) returns a uniformly random self-orthogonal vector \(\ensuremath{\mathbf{y}}\xspace_{i}\) in \(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace_{(i-1)})^\perp\) except with negligible probability in \(n\) by \cref{lem:algo:sso}. If \(\ensuremath{\mathbf{y}}\xspace_{i}\) is already in \(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace_{(i-1)})\) then it must by construction be in \(\operatorname{hull}(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace_{(i-1)}))\) and we reject it as it does not produce a new linear code. Using \cref{lem:code:variety:nsols} for \(\bullet\), we have that
  \begin{align*}
    \probsub{\ensuremath{\mathbf{y}}\xspace_i \sample \ensuremath{\mathcal{V}}_{\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace_{(i-1)})^\perp}}{\ensuremath{\mathbf{y}}\xspace_i \in \operatorname{hull}(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace_{(i-1)}))} 
    &= \frac{\left\lvert \operatorname{hull}(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace_{(i-1)})) \right\rvert}{\left\lvert \ensuremath{\mathcal{V}}_{\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace_{(i-1)})^\perp} \right\rvert}
    \overset{\bullet}{\leq} \frac{q^{i-1}}{q^{n - (k-h+i-1) - 2}} \\
    &= q^{2 i - (n - (k-h))}
    \leq q^{h - (n-k)}.
  \end{align*}
  This leads us to the following two cases.

  If it is not the case that \(k = \frac{n}{2}\) and \(h = k\), then the above is further bounded from above by \(q^{-1}\) and after repeating at most \(k\) times by \(q^{-k}\) using the union bound, which is negligible in \(k\). The probability that we succeed in sampling the hull generators \(\ensuremath{\mathbf{y}}\xspace_1,\dots,\ensuremath{\mathbf{y}}\xspace_h\) is then bounded from below by the Weierstrass product inequality as \((1 - q^{-k})^h \geq 1 - \frac{h}{q^{k}} = 1 - \negl[k]\), since we need to be successful all \(h\) times, otherwise we abort with \(\bot\). Thus, the probability that the algorithm successfully outputs a code generator matrix (rather than \(\bot\)) is overwhelming in \(k\).

  The one remaining case is that of \emph{self-dual codes}, that is \(k = \frac{n}{2}\) and \(h = k\), where the above estimate collapses. Until the last iteration, the argument is identical to the former case; we must show that the last vector \(\ensuremath{\mathbf{y}}\xspace_k\) can be chosen with overwhelming probability. In the last iteration we have a \([2 k, k-1]\)-linear self-orthogonal code spanned by \(\ensuremath{\mathbf{A}}\xspace_{(k-1)}\) and compute a generator \(\ensuremath{\mathbf{G}}\xspace\) of its dual \([2 k, k+1]\)-linear code. Since \(\ensuremath{\mathbf{G}}\xspace\) is \((k-1)\)-hollow, its hull co-dimension is precisely \(2\), thus we may run \(\ensuremath{\mathsf{SSO}}\xspace\) on it. By~\cite[Prop.~5]{ITIT:CMTQ19}. we have that \(\chi_\ensuremath{\mathbf{G}}\xspace = \chi_q(-1)^{k-1}\), hence by \cref{prop:plane:hyper} the code \(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{G}}\xspace)\) contains self-orthogonal vectors not already in \(\operatorname{hull}(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace_{(k-1)}))\) if and only if it is a hyperbolic plane with \(\chi_\ensuremath{\mathbf{G}}\xspace = \chi_q(-1)\), that is if and only if \(\chi_q(-1)^k = 1\). Recall that this is precisely when self-dual codes exist, thus we rightly always abort with \(\bot\) when they do not. Every self-orthogonal vector in \(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace_{(k-1)})^\perp\) is of the form \(\ensuremath{\mathbf{y}}\xspace = \ensuremath{\mathbf{h}}\xspace + \ensuremath{\mathbf{t}}\xspace\) with \(\ensuremath{\mathbf{h}}\xspace \in \operatorname{hull}(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace_{(k-1)})^\perp)\) and \(\ensuremath{\mathbf{t}}\xspace\) a self-orthogonal vector of the chosen hyperbolic plane. By \cref{prop:plane:hyper}, the chosen regular plane contains a non-zero self-orthogonal \(\ensuremath{\mathbf{t}}\xspace\), hence it contains the line spanned by \(\ensuremath{\mathbf{t}}\xspace\), which itself contains at least \(q\) self-orthogonal vectors. Thus
  \begin{align*}
    &\probsub{\ensuremath{\mathbf{y}}\xspace_k \sample \ensuremath{\mathcal{V}}_{\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace_{(k-1)})^\perp}}{\ensuremath{\mathbf{y}}\xspace_k \in \operatorname{hull}(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace_{(k-1)}))} 
    = \frac{\left\lvert \operatorname{hull}(\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace_{(k-1)})) \right\rvert}{\left\lvert \ensuremath{\mathcal{V}}_{\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace_{(k-1)})^\perp} \right\rvert}
    \leq \frac{q^{k-1}}{q q^{k-1}}
    \leq q^{-1}.
  \end{align*}
  We can now repeat the argument from above: after at most \(k\) repetitions, the probability of \(\ensuremath{\mathsf{SSO}}\xspace\) failing by sampling a known hull vector is bounded by \(q^{-k}\) from above, which is negligible in \(k\). Hence the probability that we succeed in sampling the self-orthogonal code generators \(\ensuremath{\mathbf{y}}\xspace_1,\dots,\ensuremath{\mathbf{y}}\xspace_k\) is bounded from below by the Weierstrass product inequality as \((1 - q^{-k})^k \geq 1 - \frac{k}{q^{k}} = 1 - \negl[k]\), since we need to be successful all \(k\) times, otherwise we abort with \(\bot\).

  \paragraph*{Uniform sampling}
  Conditioned on \(\ensuremath{\mathsf{SampleCode}}\xspace\) succeeding, we simply apply \cref{lem:hollow:unif} iteratively \(h\) times. Indeed, since \(\ensuremath{\mathbf{A}}\xspace_{(0)}\) is distributed according to \(\dist_{n,k-h,q}^{\chi,0}\) by \cref{lem:algo:samplelcd} (otherwise we abort), we have that \(\ensuremath{\mathbf{A}}\xspace_{(1)}\) is distributed according to \(\dist_{n,k-h+1,q}^{\chi,1}\) (up to re-randomisation by a random basis change, which we apply at the end). Further, \(\ensuremath{\mathbf{A}}\xspace_{(i)}\) is distributed according to \(\dist_{n,k-h+i,q}^{\chi,i}\), so the output \(\ensuremath{\mathbf{A}}\xspace = \ensuremath{\mathbf{U}}\xspace \ensuremath{\mathbf{A}}\xspace_{(h)}\) for \(\ensuremath{\mathbf{U}}\xspace \sample \mathcal{GL}_k(\FF_q)\) is distributed according to \(\dist_{n,k,q}^{\chi,h}\).

Clearly the algorithm \(\ensuremath{\mathsf{SampleHollow}}\xspace\) inherits correctness, efficiency and success probability from the algorithm \(\ensuremath{\mathsf{SampleCode}}\xspace\) in \cref{def:algo:samplecode}. The distributions \(\dist\) and \(\dist_{n,k,q}^{h}\) clearly have the same support that is the set of all generator matrices of codes in \(\mathcal{X}_{n,k,q}^{h}\). The case \(h=k\) is immediate. Otherwise, for the total variation distance \(\Delta\) we have
  \begin{align*}
    2 \Delta(\dist,\dist_{n,k,q}^h) 
    &= \sum_{\ensuremath{\left\{ \ensuremath{\mathbf{A}}\xspace \; \middle\vert \; \ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace) \in \mathcal{X}_{n,k,q}^h \right\}}} \left\lvert \prob{\ensuremath{\mathbf{A}}\xspace \sample \dist} - \prob{\ensuremath{\mathbf{A}}\xspace \sample \dist_{n,k,q}^h} \right\rvert \\
    &= \left\lvert \mathcal{X}_{n,k,q}^{+1,h} \right\rvert \left\lvert \left( \frac{1}{2 \left\lvert \mathcal{X}_{n,k,q}^{+1,h} \right\rvert} - \frac{1}{\left\lvert \mathcal{X}_{n,k,q}^h \right\rvert} \right) \right\rvert 
    + \left\lvert \mathcal{X}_{n,k,q}^{-1,h} \right\rvert \left\lvert \left( \frac{1}{2 \left\lvert \mathcal{X}_{n,k,q}^{-1,h} \right\rvert} - \frac{1}{\left\lvert \mathcal{X}_{n,k,q}^h \right\rvert} \right) \right\rvert \\
    &= \frac{\left\lvert \left\lvert \mathcal{X}_{n,k,q}^{+1,h} \right\rvert - \left\lvert \mathcal{X}_{n,k,q}^{-1,h} \right\rvert \right\rvert}{\left\lvert \mathcal{X}_{n,k,q}^h \right\rvert}
    \overset{\bullet}{\leq} 2 q^{-\frac{k-h}{2}},
  \end{align*}
  where for \(\bullet\) we use~\cite[Thm.~1]{localinv}.

\label{def:coefproj}
  Denote by \(\pi_i^{(f,z)} \colon \FF_q \to \FF_p\) for \(i \in \ZZ_d\) the \(i\)-th \emph{coefficient projection} that maps \(\pi_i^{(f, z)} \colon \sum_{j=0}^{d-1} a_j z^j \mapsto a_i\). When the polynomial \(f\) and the root \(z\) are fixed, we will often omit the superscript. We extend these maps to vectors \(\ensuremath{\mathbf{x}}\xspace \in \FF_q^n\) coordinate-wise, that is \(\pi_i(\ensuremath{\mathbf{x}}\xspace) = [\pi_i(x_j)]_{j=1}^n\), and likewise to matrices.

  Denote by \(\pi = (\pi_0,\dots,\pi_{d-1}) \colon \FF_q \to \FF_p^d\) the \(\FF_p\)-vector space isomorphism that maps \(\sum_{i=0}^{d-1} a_i z^i \mapsto [a_i]_{i=0}^{d-1}\) (cf.~\emph{coefficient embedding}), and by \(\pi^{-1}\) its inverse we call the \emph{coefficient lift}. We extend these maps to vectors and matrices, that is \(\pi^{-1}\) maps a matrix from \(\FF_p^{d \times n}\) to a vector in \(\FF_q^n\).

\label{prop:orthogonal}
  For every two vectors \(\ensuremath{\mathbf{x}}\xspace,\ensuremath{\mathbf{y}}\xspace \in \FF_q^n\) with \(q = p^d\) for \(p\) prime and \(d,n \in \NN\), and every \(r \in \ZZ_d\), we have
  \[
    \ensuremath{\left\langle \ensuremath{\mathbf{x}}\xspace, \ensuremath{\mathbf{y}}\xspace \right\rangle}_{\phi_r}
    = \sum_{i=0}^{d-1} \sum_{j=0}^{d-1} z^{i + j p^r} \ensuremath{\left\langle \pi_i(\ensuremath{\mathbf{x}}\xspace), \pi_j(\ensuremath{\mathbf{y}}\xspace) \right\rangle}.
  \]

Let us write \(c_{i,j} = \ensuremath{\left\langle \pi_i(\ensuremath{\mathbf{x}}\xspace), \pi_j(\ensuremath{\mathbf{y}}\xspace) \right\rangle}\) for brevity. Observe that setting the \(\phi_r\)-orthogonality sums from \cref{prop:orthogonal} for \(r \in \ZZ_d\) to \(0\) yields a homogeneous system of \(d^2\) linear equations in the \(d^2\) variables \(c_{i,j}\), one equation per automorphism and per degree.

  Concretely, the system is the following. Order the pairs \((i,j) \in \ZZ_d^2\) and the pairs \((r, m) \in \ZZ_d^2\) lexicographically, these will number our columns and rows, respectively. Then the system of equations we are considering is the following:
  \begin{align*}
    \ensuremath{\mathbf{A}}\xspace \ensuremath{\mathbf{c}}\xspace =
    \begin{bmatrix}
      \pi_m\left(z^{i + j p^r}\right)
    \end{bmatrix}_{\genfrac{}{}{0pt}{}{(r,m) \in \ZZ_d^2}{(i,j) \in \ZZ_d^2}}
    \begin{bmatrix}
      c_{i,j}
    \end{bmatrix}_{(i,j) \in \ZZ_d^2}^\mathtt{T}
    =
    \ensuremath{\mathbf{0}}\xspace^{d^2}.
  \end{align*}
  In words, we have \(d\) collections of \(d\) successive rows, the \(r\)-th collection corresponding to the automorphism \(\phi_r\) for \(r \in \ZZ_d\). Within each collection, the \(m\)-th row corresponds to the coefficient of degree \(m \in \ZZ_d\), we call these the degree-\(m\) rows. Our goal is to prove that the \(d^2 \times d^2\) matrix \(\ensuremath{\mathbf{A}}\xspace\) in the above equation is full-rank, meaning the only solution is \(c_{i,j} = 0\) for all \((i,j) \in \ZZ_d^2\). We use the following trick.

  Instead of considering \(\ensuremath{\mathbf{A}}\xspace\) directly, consider the non-projected \(d \times d^2\) matrix \(\ensuremath{\mathbf{A'}}\xspace = [z^{i + j p^r}]_{r \in \ZZ_d,(i,j) \in \ZZ_d^2}\). Each entry in \(\ensuremath{\mathbf{A'}}\xspace\) corresponds to a \(d\)-entry sub-column in \(\ensuremath{\mathbf{A}}\xspace\). Observe that performing rank-preserving row operations on \(\ensuremath{\mathbf{A'}}\xspace\) corresponds to rank-preserving row operations \(\ensuremath{\mathbf{A}}\xspace\), that is they factor through the coefficient projection. Indeed, adding a row to another in \(\ensuremath{\mathbf{A'}}\xspace\) corresponds to adding \(d\) rows to another \(d\) rows in \(\ensuremath{\mathbf{A}}\xspace\), and swapping two rows of \(\ensuremath{\mathbf{A'}}\xspace\) corresponds to swapping two collections of \(d\) rows of \(\ensuremath{\mathbf{A}}\xspace\). The last ingredient is that multiplying a row of \(\ensuremath{\mathbf{A'}}\xspace\) with a non-zero field element \(a \in \FF_q\) corresponds to a basis change when viewing \(\FF_q\) as a \(\FF_p\) vector space, thus it corresponds to multiplying a matrix \(\ensuremath{\mathbf{U}}\xspace_a \in \mathcal{GL}_d(\FF_p)\) to the matching \(d\) rows of \(\ensuremath{\mathbf{A}}\xspace\).

  Now we compute
  \begin{align*}
    \begin{bmatrix}
      z^{i + j p^r}
    \end{bmatrix}_{(i,j) \in \ZZ_d^2, r \in \ZZ_d}
    &=
    \begin{bmatrix}
      z^i \phi_r(z^j)
    \end{bmatrix}_{(i,j) \in \ZZ_d^2, r \in \ZZ_d} \\
    &=
    \begin{bmatrix}
      \begin{bmatrix}
        \phi_0(z^j)
      \end{bmatrix}_{j \in \ZZ_d}
      & \dots &
      \begin{bmatrix}
        \phi_0(z^j)
      \end{bmatrix}_{j \in \ZZ_d} \\
      \vdots & \ddots & \vdots \\
      \begin{bmatrix}
        \phi_{d-1}(z^j)
      \end{bmatrix}_{j \in \ZZ_d}
      & \dots &
      \begin{bmatrix}
        \phi_{d-1}(z^j)
      \end{bmatrix}_{j \in \ZZ_d}
    \end{bmatrix} 
    \cdot
    \begin{bmatrix}
      z^0 \ensuremath{\mathbf{I}}\xspace_d & & \\
      & \ddots & \\
      & & z^{d-1} \ensuremath{\mathbf{I}}\xspace_d
    \end{bmatrix} \\
    &=
    \begin{bmatrix}
      \ensuremath{\mathbf{M}}\xspace_d(z^0,\dots,z^{d-1})^\mathtt{T} & \dots & \ensuremath{\mathbf{M}}\xspace_d(z^0,\dots,z^{d-1})^\mathtt{T}
    \end{bmatrix} 
    \cdot
    \begin{bmatrix}
      z^0 \ensuremath{\mathbf{I}}\xspace_d & & \\
      & \ddots & \\
      & & z^{d-1} \ensuremath{\mathbf{I}}\xspace_d
    \end{bmatrix}
  \end{align*}
  Now recall that the Moore matrix \(\ensuremath{\mathbf{M}}\xspace_d(z^0,\dots,z^{d-1})\) is full-rank since the elements \(\set{z^0,\dots,z^{d-1}}\) form an \(\FF_p\)-basis for \(\FF_q\) as a vector space. Thus the above matrix can be transformed with row operations (by multiplying from the left with \(\ensuremath{\mathbf{M}}\xspace_d(z^0,\dots,z^{d-1})^{-\mathtt{T}}\)) into
  \begin{align*}
    &\sim
    \begin{bmatrix}
      \ensuremath{\mathbf{I}}\xspace_d & \dots & \ensuremath{\mathbf{I}}\xspace_d
    \end{bmatrix}
    \cdot
    \begin{bmatrix}
      z^0 \ensuremath{\mathbf{I}}\xspace_d & & \\
      & \ddots & \\
      & & z^{d-1} \ensuremath{\mathbf{I}}\xspace_d
    \end{bmatrix} 
    =
    \begin{bmatrix}
      z^0 \ensuremath{\mathbf{I}}\xspace_d & \dots & z^{d-1} \ensuremath{\mathbf{I}}\xspace_d
    \end{bmatrix}.
  \end{align*}
  Projecting this matrix back to a \(d^2 \times d^2\) matrix over \(\FF_p\) using coefficient embeddings yields a matrix that is clearly full-rank as it has precisely one \(1\) per row and per column, thus its determinant is \(\pm 1\). Hence \(\ensuremath{\mathbf{A}}\xspace\) is full-rank.

Suppose \(\ensuremath{\left\langle \ensuremath{\mathbf{x}}\xspace, \ensuremath{\mathbf{y}}\xspace \right\rangle}_{\phi_i} = \ensuremath{\left\langle \ensuremath{\mathbf{x}}\xspace, \phi_i(\ensuremath{\mathbf{y}}\xspace) \right\rangle} = 0\) for all \(i \in \ZZ_d\). Then also
  \begin{align*}
    \ensuremath{\left\langle \phi_i(\ensuremath{\mathbf{x}}\xspace), \phi_j(\ensuremath{\mathbf{y}}\xspace) \right\rangle}_{\phi_r}
    &= \ensuremath{\left\langle \phi_i(\ensuremath{\mathbf{x}}\xspace), \phi_{r+j}(\ensuremath{\mathbf{y}}\xspace) \right\rangle}
    = \phi_i(\ensuremath{\left\langle \ensuremath{\mathbf{x}}\xspace, \phi_{r+j-i}(\ensuremath{\mathbf{y}}\xspace) \right\rangle}) 
    = \phi_i(0)
    = 0.
  \end{align*}
  The converse is trivial. The equivalence of total orthogonality and Euclidean orthogonality of \(\Phi(\ensuremath{\mathbf{x}}\xspace)\) and \(\Phi(\ensuremath{\mathbf{y}}\xspace)\) follows from conjugate symmetry and the fact that \(\Phi(\ensuremath{\mathbf{x}}\xspace)\) and \(\Phi(\ensuremath{\mathbf{y}}\xspace)\) are closed under action with any automorphism \(\phi_i\).

\label{cor:invariant:galois}
  Assume the notation of \cref{def:galois:sqclass}.
  The function \(\chi^{\phi_i} \colon \FF_q^{k \times n} \to \set{\pm 1}\) that maps \(\ensuremath{\mathbf{A}}\xspace \mapsto \chi_{\ensuremath{\mathfrak{C}}(\ensuremath{\mathbf{A}}\xspace),\phi_i}\) for admissible \(i \in \ZZ_d\) is an efficiently computable invariant for (signed) permutation equivalence.
